package com.glassbox.chess.util; import com.glassbox.chess.domain.*; import com.glassbox.chess.rule.*; import com.glassbox.chess.piece.Piece; import java.util.*;
public final class SanConverter{private SanConverter(){}public static String toSan(Board b,Move m){if(m instanceof CastleMove)return m.getTo().getFile()==6?"O-O":"O-O-O";Piece p=m.getMovedPiece();StringBuilder s=new StringBuilder();if(p.getType()!=PieceType.PAWN)s.append(switch(p.getType()){case KING->"K";case QUEEN->"Q";case ROOK->"R";case BISHOP->"B";case KNIGHT->"N";default->"";});if(m.getCapturedPiece()!=null){if(p.getType()==PieceType.PAWN)s.append((char)('a'+m.getFrom().getFile()));s.append('x');}s.append(m.getTo().toAlgebraic());if(m instanceof PromotionMove pm)s.append("=").append(switch(pm.getPromotionType()){case QUEEN->"Q";case ROOK->"R";case BISHOP->"B";case KNIGHT->"N";default->"Q";});b.applyMove(m);Color enemy=p.getColor().opposite();boolean check=CheckDetector.isInCheck(b,enemy);boolean mate=check&&MoveValidator.getLegalMoves(b,enemy).isEmpty();b.undoMove(m);if(mate)s.append('#');else if(check)s.append('+');return s.toString();}}
